186→function handleSSEEvent(
187→  eventType: string,
188→  data: Record<string, unknown>,
189→  callbacks: AgentCallbacks,
190→) {
191→  switch (eventType) {
192→    case 'thinking':
193→    case 'answer':
194→      callbacks.onTextChunk(data.text as string);
195→      break;
196→    case 'thinking_done':
197→      callbacks.onThinkingDone();
198→      break;
199→    case 'tool_call':
200→      callbacks.onToolCall({
201→        toolCallId: (data.id as string) ?? '',
202→        toolName: (data.name as string) ?? undefined,
203→        sql: (data.sql as string) ?? '',
204→        command: (data.command as string) ?? undefined,
205→        toolInput: (data.input as Record<string, unknown>) ?? undefined,
206→        columns: [],
207→        rows: [],
208→        rowCount: 0,
209→      });
210→      break;
211→    case 'tool_result': {
212→      const result: ToolCallResult = {
213→        toolCallId: (data.id as string) ?? '',
214→        toolName: (data.name as string) ?? undefined,
215→        sql: (data.sql as string) ?? '',
216→        columns: (data.columns as string[]) ?? [],
217→        rows: (data.rows as Record<string, unknown>[]) ?? [],
218→        rowCount: (data.rowCount as number) ?? 0,
219→        error: (data.error as string) ?? undefined,
220→        output: (data.output as string) ?? undefined,
221→        rawContent: (data.content as string) ?? undefined,
222→        chart_spec: data.chart_spec
223→          ? {
224→              library: (data.chart_spec as Record<string, unknown>).library as 'plotly' | 'vegalite' | undefined,
225→              data: ((data.chart_spec as Record<string, unknown>).data as unknown[]) ?? [],
226→              layout: (data.chart_spec as Record<string, unknown>).layout as Record<string, unknown> | undefined,
227→              frames: (data.chart_spec as Record<string, unknown>).frames as unknown[] | undefined,
228→              spec: (data.chart_spec as Record<string, unknown>).spec as Record<string, unknown> | undefined,
229→            }
230→          : undefined,
231→        answerDurationMs: (data.answer_duration_ms as number) ?? undefined,
232→      };
233→      callbacks.onToolResult(result);
234→      break;
235→    }
236→    case 'subagent_start':
237→      callbacks.onSubagentStart?.({
238→        id: data.id as string,
239→        name: data.name as string,
240→        prompt: (data.prompt as string) ?? '',
241→      });
242→      break;
243→    case 'subagent_end': {
244→      type ChartSpec = { library?: 'plotly' | 'vegalite'; data: unknown[]; layout?: Record<string, unknown>; frames?: unknown[]; spec?: Record<string, unknown> };
245→      // Backend sends chart_specs (array) for multi-chart support.
246→      // Fall back to legacy chart_spec (single object) for backwards compat.
247→      const rawSpecs = data.chart_specs as ChartSpec[] | undefined;
248→      const legacySpec = data.chart_spec as ChartSpec | undefined;
249→      const chartSpecs: ChartSpec[] = rawSpecs ?? (legacySpec ? [legacySpec] : []);
250→
251→      if (chartSpecs.length > 0) {
252→        // Emit one callback per chart so each gets its own segment
253→        for (const spec of chartSpecs) {
254→          callbacks.onSubagentEnd?.({
255→            id: data.id as string,
256→            name: data.name as string,
257→            chart_spec: spec,
258→          });
259→        }
260→        // Emit text result separately (if any) so it doesn't get lost
261→        if (data.result) {
262→          callbacks.onSubagentEnd?.({
263→            id: data.id as string,
264→            name: data.name as string,
265→            result: data.result as string,
266→          });
267→        }
268→      } else {
269→        callbacks.onSubagentEnd?.({
270→          id: data.id as string,
271→          name: data.name as string,
272→          result: (data.result as string) ?? undefined,
273→          sql_results: (data.sql_results as Array<{ sql: string; columns?: string[]; rows?: Record<string, unknown>[]; rowCount?: number; error?: string }>) ?? undefined,
274→        });
275→      }
276→      break;
277→    }
278→    case 'user_question': {
279→      // Normalize options: the agent may send plain strings or {label, description} objects
280→      const rawOptions = (data.options as unknown[]) ?? [];
281→      const normalizedOptions: UserQuestionOption[] = (Array.isArray(rawOptions) ? rawOptions : []).map(
282→        (opt: unknown) => {
283→          if (typeof opt === 'string') return { label: opt };
284→          if (typeof opt === 'object' && opt !== null && 'label' in opt) return opt as UserQuestionOption;
285→          return { label: String(opt) };
286→        }
287→      );
288→      callbacks.onUserQuestion?.({
289→        questionId: data.question_id as string,
290→        question: data.question as string,
291→        options: normalizedOptions,
292→        multiSelect: (data.multi_select as boolean) ?? false,
293→      });
294→      break;
295→    }
296→    case 'done':
297→      callbacks.onDone((data.session_id as string) ?? null);
298→      break;
