653→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...state.segments], durationMs }
654→                  : m
655→              )
656→            );
657→            if (convId && activeConversationIdRef.current !== convId) {
658→              messagesCacheRef.current.set(convId, state.messages);
659→            }
660→            cleanupStream();
661→            if (activeConversationIdRef.current === convId) {
662→              setIsStreaming(false);
663→            }
664→          },
665→          onError: (error) => {
666→            flushNow();
667→            if (state.currentText.trim()) {
668→              const segType = state.phase === 'answer' ? 'answer' : 'thinking';
669→              state.segments.push({ type: segType, text: state.currentText });
670→              state.currentText = '';
671→            }
672→            state.segments.push({ type: 'error', errorMessage: error });
673→            const durationMs = Date.now() - state.startTime;
674→            updateMessages(msgs =>
675→              msgs.map(m =>
676→                m.id === assistantId
677→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...state.segments], durationMs }
678→                  : m
679→              )
680→            );
681→            if (convId && activeConversationIdRef.current !== convId) {
682→              messagesCacheRef.current.set(convId, state.messages);
683→            }
684→            cleanupStream();
685→            if (activeConversationIdRef.current === convId) {
686→              setIsStreaming(false);
687→            }
688→          },
689→          onUserQuestion: (data) => {
690→            flushNow();
691→            if (state.currentText.trim()) {
692→              const segType = state.phase === 'answer' ? 'answer' : 'thinking';
693→              state.segments.push({ type: segType, text: state.currentText });
694→              state.currentText = '';
695→            }
696→            state.segments.push({ type: 'user_question', questionData: data });
697→            updateMessages(msgs =>
698→              msgs.map(m =>
699→                m.id === assistantId
700→                  ? { ...m, segments: [...state.segments] }
701→                  : m
702→              )
703→            );
704→          },
705→        },
706→        controller.signal,
707→        userSessionId,
708→        convId,
709→        chartLibrary,
710→      );
711→    },
712→    [flushTextForStream, refreshTables, userSessionId, chartLibrary]
713→  );
714→
715→  const deleteMessage = useCallback(
716→    (messageIndex: number) => {
717→      const convId = activeConversationIdRef.current;
718→      // Only block if this specific conversation is streaming
719→      if (convId && streamStatesRef.current.has(convId)) return;
720→
721→      // Store remaining messages as history for Langfuse context on next send
722→      setMessages((prev) => {
723→        const remaining = prev.slice(0, messageIndex);
724→        pendingHistoryRef.current = remaining
725→          .filter((m) => m.role === 'user' || m.role === 'assistant')
726→          .map((m) => ({ role: m.role, content: m.content }));
727→        return remaining;
728→      });
729→
730→      // Persist the truncation to the backend
731→      if (convId) {
732→        fetch(`/api/conversations/${convId}/messages?from_sort_order=${messageIndex}`, {
733→          method: 'DELETE',
734→        }).catch(() => {
735→          // Best-effort: if this fails the UI is already updated
736→        });
737→        // Invalidate cache so switching back loads from backend
738→        messagesCacheRef.current.delete(convId);
739→      }
740→
741→      // Clear session so next message starts fresh
742→      sessionIdRef.current = null;
743→    },
744→    []
745→  );
746→
747→  const respondToQuestion = useCallback(
748→    async (questionId: string, answers: string[], freeText?: string) => {
749→      // Find the stream state that contains this question
750→      let targetState: StreamState | undefined;
751→      let targetConvId: string | null = null;
752→
753→      // Search all active streams for the question
754→      for (const [cid, state] of streamStatesRef.current) {
755→        if (state.segments.some(s => s.type === 'user_question' && s.questionData?.questionId === questionId)) {
756→          targetState = state;
757→          targetConvId = cid;
758→          break;
759→        }
760→      }
761→
762→      if (targetState) {
763→        const segIdx = targetState.segments.findIndex(
764→          s => s.type === 'user_question' && s.questionData?.questionId === questionId
765→        );
766→        if (segIdx !== -1) {
767→          targetState.segments[segIdx] = {
768→            ...targetState.segments[segIdx],
769→            userAnswer: answers,
770→            userFreeText: freeText,
771→          };
772→          targetState.messages = targetState.messages.map(m =>
773→            m.id === targetState!.assistantId
774→              ? { ...m, segments: [...targetState!.segments] }
775→              : m
776→          );
777→          if (activeConversationIdRef.current === targetConvId) {
778→            setMessages(targetState.messages);
779→          }
780→        }
781→      }
782→
783→      // POST to backend
784→      try {
785→        await fetch('/api/chat/respond', {
786→          method: 'POST',
787→          headers: {
788→            'Content-Type': 'application/json',
789→            ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
790→          },
791→          body: JSON.stringify({
792→            question_id: questionId,
793→            answers,
794→            free_text: freeText || null,
795→          }),
796→        });
797→      } catch (e) {
798→        console.error('Failed to respond to question:', e);
799→      }
800→    },
801→    [userSessionId]
802→  );
803→
804→  const loadMessages = useCallback((msgs: ChatMessage[], outgoingConversationId?: string | null, incomingConversationId?: string | null) => {
805→    const outgoing = outgoingConversationId || null;
806→    const incoming = incomingConversationId || null;
807→    activeConversationIdRef.current = incoming;
808→
809→    // Save outgoing conversation's messages to cache (only if not streaming --
810→    // streaming conversations keep their state in streamStatesRef)
811→    if (outgoing && !streamStatesRef.current.has(outgoing)) {
812→      const currentMsgs = messagesRef.current;
813→      if (currentMsgs.length > 0) {
814→        messagesCacheRef.current.set(outgoing, currentMsgs);
815→      }
816→    }
817→
818→    // Check if incoming conversation has an active stream (re-attachment)
819→    if (incoming) {
820→      const streamState = streamStatesRef.current.get(incoming);
821→      if (streamState) {
822→        // Re-attach: use live stream messages
823→        setMessages(streamState.messages);
824→        setIsStreaming(true);
825→        return;
826→      }
827→    }
828→
829→    // No active stream -- use backend data or cache
830→    let finalMsgs = msgs;
831→    if (incoming) {
832→      const cached = messagesCacheRef.current.get(incoming);
833→      if (cached && cached.length > 0 && cached.length > msgs.length) {
834→        finalMsgs = cached;
835→      }
836→      messagesCacheRef.current.delete(incoming);
837→    }
838→
839→    setMessages(finalMsgs);
840→    const hasStreamingMsg = finalMsgs.some(m => m.isStreaming);
841→    setIsStreaming(hasStreamingMsg);
842→    sessionIdRef.current = null;
843→    pendingHistoryRef.current = null;
844→  }, []);
845→
846→  const clearMessages = useCallback((outgoingConversationId?: string | null) => {
847→    const outgoing = outgoingConversationId || null;
848→    activeConversationIdRef.current = null;
849→
850→    // Save outgoing messages to cache if not streaming
851→    if (outgoing && !streamStatesRef.current.has(outgoing)) {
852→      const currentMsgs = messagesRef.current;
853→      if (currentMsgs.length > 0) {
854→        messagesCacheRef.current.set(outgoing, currentMsgs);
855→      }
856→    }
857→
858→    setMessages([]);
859→    setIsStreaming(false);
860→    sessionIdRef.current = null;
861→    pendingHistoryRef.current = null;
862→  }, []);
863→
864→  return (
865→    <AgentContext.Provider
866→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, loadMessages, respondToQuestion, streamingConversationIds }}
867→    >
868→      {children}
869→    </AgentContext.Provider>
870→  );
871→}
