60→              if (seg.userFreeText) s.userFreeText = seg.userFreeText as string;
61→              if (seg.answerDurationMs) s.answerDurationMs = seg.answerDurationMs as number;
62→            }
63→            return s;
64→          });
65→        }
66→      } catch {
67→        // metadata parse failed, fall through to default
68→      }
69→    }
70→
71→    // Fallback: single answer segment from content
72→    if (!segments) {
