      const cleanupStream = () => {
        if (state.flushTimer) {
          clearTimeout(state.flushTimer);
          state.flushTimer = null;
        }
        if (convId) {
          streamStatesRef.current.delete(convId);
          setStreamingConversationIds(prev => {
            const next = new Set(prev);
            if (convId) next.delete(convId);
            return next;
          });
        }
      };

