  2→
  3→interface AgentCallbacks {
  4→  onTextChunk: (text: string) => void;
  5→  onThinkingDone: () => void;
  6→  onToolCall: (pending: ToolCallResult) => void;
  7→  onToolResult: (result: ToolCallResult) => void;
  8→  onSubagentStart?: (data: { id: string; name: string; prompt: string }) => void;
  9→  onSubagentThinking?: (data: { id: string; text: string }) => void;
 10→  onSubagentEnd?: (data: { id: string; name: string; result?: string; thinking?: string; sql_results?: Array<{ sql: string; columns?: string[]; rows?: Record<string, unknown>[]; rowCount?: number; error?: string }>; chart_spec?: { library?: 'plotly' | 'vegalite'; data: unknown[]; layout?: Record<string, unknown>; frames?: unknown[]; spec?: Record<string, unknown> } }) => void;
 11→  onDone: (sessionId: string | null) => void;
 12→  onError: (error: string) => void;
 13→  onUserQuestion?: (data: UserQuestionData) => void;
 14→}
 15→
 16→export type { AgentCallbacks };
 17→
 18→async function streamSSE(
 19→  response: Response,
 20→  callbacks: AgentCallbacks,
 21→  signal?: AbortSignal,
 22→): Promise<void> {
 23→  const reader = response.body?.getReader();
 24→  if (!reader) {
 25→    callbacks.onError('No response stream');
 26→    return;
 27→  }
 28→
 29→  let doneReceived = false;
 30→  const wrappedCallbacks: AgentCallbacks = {
 31→    ...callbacks,
 32→    onDone: (sessionId) => {
 33→      doneReceived = true;
 34→      callbacks.onDone(sessionId);
 35→    },
 36→    onError: (error) => {
 37→      doneReceived = true;
 38→      callbacks.onError(error);
 39→    },
 40→  };
 41→
 42→  try {
 43→    const decoder = new TextDecoder();
 44→    let buffer = '';
 45→    let eventType = '';
 46→
 47→    while (true) {
 48→      const { done, value } = await reader.read();
 49→      if (done) break;
 50→
 51→      buffer += decoder.decode(value, { stream: true });
 52→      const lines = buffer.split('\n');
 53→      buffer = lines.pop() ?? '';
 54→      for (const line of lines) {
 55→        if (line.startsWith('event: ')) {
 56→          eventType = line.slice(7).trim();
 57→        } else if (line.startsWith('data: ')) {
 58→          const data = line.slice(6);
 59→          try {
 60→            const parsed = JSON.parse(data);
 61→            handleSSEEvent(eventType, parsed, wrappedCallbacks);
 62→          } catch {
 63→            // Skip malformed JSON
 64→          }
 65→          eventType = '';
 66→        }
 67→      }
 68→    }
 69→
 70→    // Process any remaining data left in buffer after stream ends
 71→    if (buffer.trim()) {
 72→      const remainingLines = buffer.split('\n');
 73→      for (const line of remainingLines) {
 74→        if (line.startsWith('event: ')) {
 75→          eventType = line.slice(7).trim();
 76→        } else if (line.startsWith('data: ')) {
 77→          const data = line.slice(6);
 78→          try {
 79→            const parsed = JSON.parse(data);
 80→            handleSSEEvent(eventType, parsed, wrappedCallbacks);
 81→          } catch {
 82→            // Skip malformed JSON
 83→          }
 84→          eventType = '';
 85→        }
 86→      }
 87→    }
 88→
 89→    // Safety net: if stream ended without done/error, force done
 90→    if (!doneReceived) {
 91→      callbacks.onDone(null);
 92→    }
 93→  } catch (e: unknown) {
 94→    if (signal?.aborted) return;
 95→    const msg = e instanceof Error ? e.message : 'Connection failed';
 96→    callbacks.onError(msg);
 97→  }
 98→}
