100→export async function runAgentLoop(
101→  message: string,
102→  agentSessionId: string | null,
103→  langfuseSessionId: string | null,
104→  conversationHistory: { role: string; content: string }[] | null,
105→  conversationId?: string | null,
106→  callbacks?: AgentCallbacks,
107→  signal?: AbortSignal,
108→  userSessionId?: string,
109→  skills?: string[],
110→  chartLibrary?: string,
111→): Promise<void> {
112→  if (!callbacks) return;
113→  try {
114→    const response = await fetch('/api/chat', {
115→      method: 'POST',
116→      headers: {
117→        'Content-Type': 'application/json',
118→        ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
119→      },
120→      body: JSON.stringify({
121→        message,
122→        session_id: agentSessionId,
123→        conversation_id: conversationId,
124→        langfuse_session_id: langfuseSessionId,
125→        conversation_history: conversationHistory ?? [],
126→        ...(skills?.length ? { skills } : {}),
127→        chart_library: chartLibrary || 'plotly',
128→      }),
129→      signal,
130→    });
131→
132→    if (!response.ok) {
133→      const errorText = await response.text();
134→      callbacks.onError(`Server error: ${errorText}`);
135→      return;
136→    }
137→
