187→function handleSSEEvent(
188→  eventType: string,
189→  data: Record<string, unknown>,
190→  callbacks: AgentCallbacks,
191→) {
192→  switch (eventType) {
193→    case 'thinking':
194→    case 'answer':
195→      callbacks.onTextChunk(data.text as string);
196→      break;
197→    case 'thinking_done':
198→      callbacks.onThinkingDone();
199→      break;
200→    case 'tool_call':
201→      callbacks.onToolCall({
202→        toolCallId: (data.id as string) ?? '',
203→        toolName: (data.name as string) ?? undefined,
204→        sql: (data.sql as string) ?? '',
205→        command: (data.command as string) ?? undefined,
206→        toolInput: (data.input as Record<string, unknown>) ?? undefined,
207→        columns: [],
208→        rows: [],
209→        rowCount: 0,
210→      });
211→      break;
212→    case 'tool_result': {
213→      const result: ToolCallResult = {
214→        toolCallId: (data.id as string) ?? '',
215→        toolName: (data.name as string) ?? undefined,
216→        sql: (data.sql as string) ?? '',
217→        columns: (data.columns as string[]) ?? [],
218→        rows: (data.rows as Record<string, unknown>[]) ?? [],
219→        rowCount: (data.rowCount as number) ?? 0,
220→        error: (data.error as string) ?? undefined,
221→        output: (data.output as string) ?? undefined,
222→        rawContent: (data.content as string) ?? undefined,
223→        chart_spec: data.chart_spec
224→          ? {
225→              library: (data.chart_spec as Record<string, unknown>).library as 'plotly' | 'vegalite' | undefined,
226→              data: ((data.chart_spec as Record<string, unknown>).data as unknown[]) ?? [],
227→              layout: (data.chart_spec as Record<string, unknown>).layout as Record<string, unknown> | undefined,
228→              frames: (data.chart_spec as Record<string, unknown>).frames as unknown[] | undefined,
229→              spec: (data.chart_spec as Record<string, unknown>).spec as Record<string, unknown> | undefined,
230→            }
231→          : undefined,
232→        answerDurationMs: (data.answer_duration_ms as number) ?? undefined,
233→      };
234→      callbacks.onToolResult(result);
235→      break;
236→    }
237→    case 'subagent_start':
238→      callbacks.onSubagentStart?.({
239→        id: data.id as string,
240→        name: data.name as string,
241→        prompt: (data.prompt as string) ?? '',
242→      });
243→      break;
244→    case 'subagent_thinking':
245→      callbacks.onSubagentThinking?.({
246→        id: data.id as string,
247→        text: data.text as string,
248→      });
249→      break;

249→      break;
250→    case 'subagent_end': {
251→      type ChartSpec = { library?: 'plotly' | 'vegalite'; data: unknown[]; layout?: Record<string, unknown>; frames?: unknown[]; spec?: Record<string, unknown> };
252→      // Backend sends chart_specs (array) for multi-chart support.
253→      // Fall back to legacy chart_spec (single object) for backwards compat.
254→      const rawSpecs = data.chart_specs as ChartSpec[] | undefined;
255→      const legacySpec = data.chart_spec as ChartSpec | undefined;
256→      const chartSpecs: ChartSpec[] = rawSpecs ?? (legacySpec ? [legacySpec] : []);
257→
258→      const saThinking = (data.thinking as string) ?? undefined;
259→
260→      if (chartSpecs.length > 0) {
261→        // Emit one callback per chart so each gets its own segment
262→        for (const spec of chartSpecs) {
263→          callbacks.onSubagentEnd?.({
264→            id: data.id as string,
265→            name: data.name as string,
266→            chart_spec: spec,
267→          });
268→        }
269→        // Emit text result separately (if any) so it doesn't get lost
270→        if (data.result || saThinking) {
271→          callbacks.onSubagentEnd?.({
272→            id: data.id as string,
273→            name: data.name as string,
274→            result: (data.result as string) ?? undefined,
275→            thinking: saThinking,
276→          });
277→        }
278→      } else {
279→        callbacks.onSubagentEnd?.({
280→          id: data.id as string,
281→          name: data.name as string,
282→          result: (data.result as string) ?? undefined,
283→          thinking: saThinking,
284→          sql_results: (data.sql_results as Array<{ sql: string; columns?: string[]; rows?: Record<string, unknown>[]; rowCount?: number; error?: string }>) ?? undefined,
285→        });
286→      }
287→      break;
288→    }
289→    case 'user_question': {
290→      // Normalize options: the agent may send plain strings or {label, description} objects
291→      const rawOptions = (data.options as unknown[]) ?? [];
292→      const normalizedOptions: UserQuestionOption[] = (Array.isArray(rawOptions) ? rawOptions : []).map(
293→        (opt: unknown) => {
294→          if (typeof opt === 'string') return { label: opt };
295→          if (typeof opt === 'object' && opt !== null && 'label' in opt) return opt as UserQuestionOption;
296→          return { label: String(opt) };
297→        }
298→      );
299→      callbacks.onUserQuestion?.({
300→        questionId: data.question_id as string,
301→        question: data.question as string,
302→        options: normalizedOptions,
303→        multiSelect: (data.multi_select as boolean) ?? false,
304→      });
305→      break;
306→    }
307→    case 'done':
308→      callbacks.onDone((data.session_id as string) ?? null);
309→      break;
310→    case 'error':
311→      callbacks.onError((data.message as string) ?? 'Unknown error');
312→      break;
313→  }
314→}
